package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.GroupItem;
import com.mhtextractor.model.PreviewItem;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * 撤销载荷构造工厂（P1-4）：gui 层三条 {@code new UndoManager.Record<>(...)} 的<b>唯一构造出口</b>，
 * 构造下沉到 app 层（零 JavaFX、零 I18n），gui 调用方只负责压栈（{@code ws.push(...)} /
 * {@code host.pushUndo(...)}），压栈时机与顺序不变。
 *
 * <p><b>只搬不改</b>：字段值、构造参数与搬移前逐字一致（含 {@code List.of()} 占位、{@code -1}、
 * {@code false}、{@code null} 的位置；IMPORT 的 {@code new ArrayList<>} 拷贝语义保持在工厂内）。</p>
 */
public final class UndoRecords {

    private UndoRecords() {
    }

    /** IMPORT 三参重载：一次导入 = 一条记录携带全部自动创建的组（BC-5）；拷贝语义与搬移前一致。 */
    public static UndoManager.Record<PreviewItem> importRecord(List<PreviewItem> items,
                                                               List<GroupItem<PreviewItem>> groups) {
        return new UndoManager.Record<>(UndoManager.RecordType.IMPORT,
                new ArrayList<>(items), new ArrayList<>(groups));
    }

    /** APPLY_GLOBAL 全参记录：应用前的全局参数 + 全部独立参数快照，撤销可完整回退。 */
    public static UndoManager.Record<PreviewItem> applyGlobal(boolean imageMode, AppConfig globalBefore,
                                                              Map<String, AppConfig> itemBefore,
                                                              Map<Integer, AppConfig> groupBefore) {
        return new UndoManager.Record<>(UndoManager.RecordType.APPLY_GLOBAL, List.of(),
                null, -1, List.of(), List.of(), List.of(), List.of(),
                imageMode, globalBefore, itemBefore, groupBefore, false, null, null, null,
                false, null, null);
    }

    /** CLEAR_PARAMS 全参记录：清除前的该模式条目级/组级参数快照。 */
    public static UndoManager.Record<PreviewItem> clearParams(boolean imageMode,
                                                              Map<String, AppConfig> itemBefore,
                                                              Map<Integer, AppConfig> groupBefore) {
        return new UndoManager.Record<>(UndoManager.RecordType.CLEAR_PARAMS, List.of(),
                null, -1, List.of(), List.of(), List.of(), List.of(),
                false, null, null, null, false, null, null, null,
                imageMode, itemBefore, groupBefore);
    }
}
package com.mhtextractor.app;

import com.mhtextractor.cache.PreviewCacheLifecycle;
import com.mhtextractor.model.PreviewItem;

import java.util.ArrayList;
import java.util.List;

/**
 * 工作区缓存失效服务（会话 18 · E2.2）—— {@code com.mhtextractor.app} 的**第一个类**。
 *
 * <p><b>解决什么问题</b>：预览缓存的"四条生命周期规则"原先由 {@code MainController} 在
 * <b>12 处</b>手工调用：5 个参数写入点（{@code applyItemParams}/{@code applyConfirmedParams}/
 * {@code applyGroupParams}/{@code applyGlobalParamsTo}/{@code clearParamsForTargets}）、
 * 2 个移除点（{@code removeItems}/{@code removeGroup}）、以及 {@code onUndoClicked} 的
 * <b>5 个分支</b>（撤销导入/PARAM_SET/GROUP 参数/全局参数/CLEAR_PARAMS）。
 * 这种"每个分支自己记得调一次"的形态正是耦合点 #11 与"分支漏调"类 bug 的温床
 * （{@code docs/全量链路清单.md} 耦合点 #11）。</p>
 *
 * <p><b>本类做什么</b>：把"参数已变 / 条目已移除 → 失效其磁盘预览缓存"收敛为两个具名操作，
 * 调用方不再直接触碰 {@link PreviewCacheLifecycle} 的规则方法。语义与原先<b>逐字一致</b>：
 * 只负责磁盘缓存目录的失效，内存态（{@code cachedText/Thumbs/Meta…}）仍由控制器侧的
 * {@code clearPreviewCache} 负责 —— 两者原本就是互补的两件事，本类刻意不合并它们
 * （合并会改变行为，见 R4）。</p>
 *
 * <p><b>为什么放在 {@code app} 包</b>：本类<b>零 JavaFX 依赖</b>，只依赖
 * {@code cache} 与 {@code model} 两个业务包。放在 {@code app} 是为了让它成为目标 ② 里
 * "无头应用层"的第一块砖，并由 {@code ArchitectureTest} 强制其依赖闭包不含 {@code javafx}。</p>
 *
 * <p><b>不变式</b>：{@code imageMode == false} 时<b>不做任何事</b> —— 这是原代码在每个调用点的
 * 共同守卫（文本模式参数与图片预览缓存无关）。本类把该守卫收敛到内部，避免调用方各自判断时漏写。</p>
 */
public final class WorkspaceParamService {

    private final PreviewCacheLifecycle previewCacheLifecycle;

    public WorkspaceParamService(PreviewCacheLifecycle previewCacheLifecycle) {
        this.previewCacheLifecycle = previewCacheLifecycle;
    }

    /**
     * 规则 (a)：参数已变 → 删除受影响条目的磁盘预览缓存目录。
     *
     * <p>与原先各调用点的行为一致：仅在 {@code imageMode} 为真时执行；集合为空时不产生副作用
     * （{@link PreviewCacheLifecycle#onParamsChangedBatch} 最终委托的 {@code onItemsRemoved}
     * 对空集合本就提前返回 0，故跳过调用与调用空集合<b>语义等价</b>）。</p>
     *
     * <p><b>刻意不提供 {@code List<String>} 重载</b>：它与本重载对 {@code null} 实参有歧义
     * （实测编译报"对 paramsChanged 的引用不明确"）。调用方一律传条目集合，语义更清楚，
     * 也避免调用方自己拼路径时漏做 null 过滤。</p>
     *
     * @param imageMode true = 图片模式（文本模式参数变化不影响图片缓存，直接跳过）
     * @param items     受影响条目（null 与空集合均为 no-op）
     */
    public void paramsChanged(boolean imageMode, Iterable<PreviewItem> items) {
        if (!imageMode || items == null) {
            return;
        }
        List<String> paths = new ArrayList<>();
        for (PreviewItem it : items) {
            if (it != null && it.path != null) {
                paths.add(it.path);
            }
        }
        if (!paths.isEmpty()) {
            previewCacheLifecycle.onParamsChangedBatch(paths);
        }
    }

    /** 单条目便捷重载（对应原先的 {@code onParamsChanged(path)}） */
    public void paramsChanged(boolean imageMode, PreviewItem item) {
        if (!imageMode || item == null) {
            return;
        }
        previewCacheLifecycle.onParamsChanged(item.path);
    }

    /**
     * 规则 (c)：条目已从列表移除 → 删除其磁盘预览缓存目录。
     *
     * <p>注意：本规则<b>没有</b> {@code imageMode} 守卫 —— 原代码在移除路径上也无条件调用
     * （移除条目后无论当前是什么模式，其图片缓存都不该保留）。此处保持一致。</p>
     *
     * @param items 被移除的条目
     */
    public void itemsRemoved(Iterable<PreviewItem> items) {
        if (items == null) {
            return;
        }
        List<String> paths = new ArrayList<>();
        for (PreviewItem it : items) {
            if (it != null && it.path != null) {
                paths.add(it.path);
            }
        }
        if (!paths.isEmpty()) {
            previewCacheLifecycle.onItemsRemoved(paths);
        }
    }

    /**
     * 规则 (d)：退出前清空整个会话缓存（只清本应用专属根目录，绝不触碰 java.io.tmpdir 整体）。
     *
     * <p>F 阶段收口：GUI 关窗链原先直接调 {@link PreviewCacheLifecycle#onShutdown}
     * （{@code MainController} 宿主适配），违反"GUI 不得直调缓存规则"不变式 ——
     * {@code ArchitectureTest.guiLayerDoesNotInvokeCacheRulesDirectly} 的 ruleMethods 现已含
     * {@code onShutdown}。清空完成后的回调与旧调用点逐字一致（空实现：放行关窗由调用方的
     * 等待卡片收尾负责，不经该回调）。IO 失败不抛（退出路径不允许因缓存问题阻止关闭，
     * 见 {@link PreviewCacheLifecycle#onShutdown}）。</p>
     *
     * <p><b>为何不叫 {@code onShutdown}</b>：不变式按 {@code .onShutdown(} 字形扫 GUI 层，
     * 若本方法同名，路由调用本身会被误报（实测）。本方法名取规则语义而非生命周期回调名。</p>
     */
    public void clearAllCaches() {
        previewCacheLifecycle.onShutdown(() -> { });
    }

    // ==================== 只读查询（不含规则语义，纯转发） ====================

    /**
     * 是否还有未清理的预览缓存目录（关窗链的"是否需要提示先清空"判据）。
     *
     * <p>这是**只读查询**，不含任何规则语义；放在本服务是为了让控制器不必直接持有
     * {@link PreviewCacheLifecycle} 的查询面。真正的缓存读写（{@code store()}）将在
     * E4 抽 `PreviewService` 时一并收口 —— 那是预览加载路径的职责，不属于参数/移除规则。</p>
     */
    public boolean hasCachedEntries() {
        return previewCacheLifecycle.hasCachedEntries();
    }
}

    /** 参数类撤销分支（C4）：{@link WorkspaceLifecycleController#onUndoClicked} 的 PARAM_SET / CLEAR_PARAMS /
     *  APPLY_GLOBAL 三个 case 体逐字搬入（含对 restoreParamSnapshots / refreshAfterParamsChanged /
     *  clearExtractOutcomes / paramsChanged / startPreParseFor / 两参数缓存 /
     *  updateInfoArea / updateExtractBanner / updateListButtons / modeWord 的调用）。 */
    void applyParamUndo(UndoManager.Record<PreviewItem> record) {
        switch (record.type()) {
            case PARAM_SET -> {
                // 条目独立参数需求拍板：设置参数类操作（条目/组/全局）可撤销，恢复设置前的参数
                boolean im = record.paramImageMode();
                if (!record.clearItemParamsBefore().isEmpty() || !record.clearGroupParamsBefore().isEmpty()) {
                    // Q10/R7.5 批量「应用到所选」：一条记录携带全部目标的 before 快照，
                    // 恢复与 CLEAR_PARAMS 撤销共用同一份实现（不另写一套）
                    restoreParamSnapshots(im, record.clearItemParamsBefore(), record.clearGroupParamsBefore());
                } else if (record.paramTargetPath() != null) {
                    for (PreviewItem it : host.allPreviewItems()) {
                        if (it.path.equals(record.paramTargetPath())) {
                            if (im) {
                                it.imageItemParams = record.paramBefore();
                            } else {
                                it.textItemParams = record.paramBefore();
                            }
                            host.clearExtractOutcomes(List.of(it));
                            host.clearPreviewCache(it);
                            // 规则 (a)：撤销恢复旧参数 = 生效参数变化 → 删该项目缓存目录
                            host.paramsChanged(im, it);
                            host.startPreParseFor(List.of(it));
                            break;
                        }
                    }
                } else if (record.paramTargetGroupNo() != null) {
                    for (Object o : host.dataOrder()) {
                        if (o instanceof GroupItem<?> g
                                && g.getGroupNo() == record.paramTargetGroupNo()) {
                            GroupItem<PreviewItem> grp = WorkspaceStructure.asPreviewGroup(g);
                            if (im) {
                                grp.setImageParamsCache(record.paramBefore());
                            } else {
                                grp.setTextParamsCache(record.paramBefore());
                            }
                            List<PreviewItem> members = grp.getMembers().stream()
                                    .filter(m -> !m.removed).toList();
                            host.clearExtractOutcomes(members);
                            for (PreviewItem m : members) {
                                host.clearPreviewCache(m);
                            }
                            // 规则 (a)：撤销恢复组参数 → 成员生效参数变化 → 删其缓存目录
                            host.paramsChanged(im, members);
                            host.startPreParseFor(members);
                            break;
                        }
                    }
                } else {
                    if (im) {
                        globalParams.set(true, record.paramBefore());
                    } else {
                        globalParams.set(false, record.paramBefore());
                    }
                    host.clearExtractOutcomes(host.allPreviewItems());
                    // 规则 (a)：撤销恢复全局参数 → 全部条目生效参数可能变化 → 保守全删
                    host.paramsChanged(im, host.allPreviewItems());
                    refreshAfterParamsChanged();
                }
                host.fileListView().refresh();
                host.updateInfoArea(host.currentSelection());
                host.updateExtractBanner(host.currentSelection());
                host.updateListButtons();
                log.info(Texts.msg("log.maincontroller.53", modeWord(im)));
            }
            case CLEAR_PARAMS -> {
                // 清除参数拍板 Q4：按 before 快照一次恢复全部被清除的条目/组参数，并重走联动刷新
                boolean im = record.clearImageMode();
                Map<Integer, AppConfig> groupBefore = record.clearGroupParamsBefore();
                int restoredItems = restoreParamSnapshots(im, record.clearItemParamsBefore(), groupBefore);
                log.info(Texts.msg("log.maincontroller.54", modeWord(im), restoredItems, groupBefore.size()));
            }
            case APPLY_GLOBAL -> {
                // 条目独立参数需求拍板：恢复应用前的全局参数与全部独立参数快照
                boolean im = record.applyGlobalImageMode();
                if (im) {
                    globalParams.set(true, record.applyGlobalBefore());
                } else {
                    globalParams.set(false, record.applyGlobalBefore());
                }
                Map<String, AppConfig> itemBefore = record.applyGlobalItemParamsBefore();
                for (PreviewItem it : host.allPreviewItems()) {
                    if (itemBefore.containsKey(it.path)) {
                        AppConfig p = itemBefore.get(it.path);
                        if (im) {
                            it.imageItemParams = p;
                        } else {
                            it.textItemParams = p;
                        }
                    }
                }
                Map<Integer, AppConfig> groupBefore = record.applyGlobalGroupParamsBefore();
                for (Object o : host.dataOrder()) {
                    if (o instanceof GroupItem<?> g) {
                        if (groupBefore.containsKey(g.getGroupNo())) {
                            AppConfig p = groupBefore.get(g.getGroupNo());
                            if (im) {
                                g.setImageParamsCache(p);
                            } else {
                                g.setTextParamsCache(p);
                            }
                        }
                    }
                }
                host.clearExtractOutcomes(host.allPreviewItems());
                // 规则 (a)：撤销应用到全局 → 全部条目生效参数可能变化 → 保守全删
                host.paramsChanged(im, host.allPreviewItems());
                refreshAfterParamsChanged();
                host.updateListButtons();
                host.updateExtractBanner(host.currentSelection());
                log.info(Texts.msg("log.maincontroller.55", modeWord(im)));
            }
        }
    }

    /** 按 (path | groupNo → AppConfig) 快照恢复参数并重走联动刷新与缓存失效（清除参数 / 批量应用共用） */
    private int restoreParamSnapshots(boolean im, Map<String, AppConfig> itemBefore,
                                      Map<Integer, AppConfig> groupBefore) {
        List<PreviewItem> restoredItems = new ArrayList<>();
        for (PreviewItem it : host.allPreviewItems()) {
            if (itemBefore.containsKey(it.path)) {
                if (im) it.imageItemParams = itemBefore.get(it.path);
                else it.textItemParams = itemBefore.get(it.path);
                restoredItems.add(it);
            }
        }
        List<PreviewItem> affected = new ArrayList<>(restoredItems);
        for (Object o : host.dataOrder()) {
            if (o instanceof GroupItem<?> g) {
                GroupItem<PreviewItem> grp = WorkspaceStructure.asPreviewGroup(g);
                if (groupBefore.containsKey(grp.getGroupNo())) {
                    if (im) grp.setImageParamsCache(groupBefore.get(grp.getGroupNo()));
                    else grp.setTextParamsCache(groupBefore.get(grp.getGroupNo()));
                    affected.addAll(grp.getMembers().stream()
                            .filter(m -> !m.removed).toList());
                }
            }
        }
        host.clearExtractOutcomes(affected);
        // 规则 (a)：撤销恢复旧参数 = 生效参数变化 → 删受影响条目缓存目录（经 WorkspaceParamService 收口）
        host.paramsChanged(im, affected);
        refreshAfterTargetedParamsChange(affected);
        host.updateListButtons();
        host.updateExtractBanner(host.currentSelection());
        return restoredItems.size();
    }

    /** 日志文案里的模式词（图片/文本 → Image/Text），供 log.* 模板的 {0} 占位符使用 */
    private static String modeWord(boolean imageMode) {
        return Texts.get(imageMode ? "mode.image" : "mode.text");
    }
}
    }

    // ==================== 变更：撤销 ====================

    /**
     * 撤销一步。
     *
     * <p><b>范围说明（诚实标注）</b>：本类实现与"列表结构"相关的撤销类型
     * （{@code IMPORT / GROUP / UNGROUP / REMOVE / REMOVE_GROUP}），
     * 覆盖了"桩 UI 跑通工作区功能"与生产 GUI 的结构类撤销所需。
     * 参数类撤销（{@code PARAM_SET / CLEAR_PARAMS / APPLY_GLOBAL}）<b>仍</b>未纳入 ——
     * 它们需要参数快照与作用域寻址，属后续步骤（见 {@code docs/handoff/H17.md}）。
     * 原本文中列为"尚未纳入"的 {@code REORDER / MERGE_GROUPS} 已于 Q0/P0 纳入本类
     * （见 {@link #applyUndo}：恢复方式是结构快照，不需要落点解析）。</p>
     *
     * @return true = 确实撤销了一步；false = 栈空或该类型尚未支持（不产生任何变更）
     */
    public boolean undo() {
        if (undoManager.isEmpty()) {
            return false;
        }
        // UndoManager 只提供 pop()（无 peek）。故先弹出，遇到尚未支持的类型再原样压回 ——
        // 这样"不支持"不会静默改变状态（若直接忽略，用户会看到"撤销了但什么都没变"）。
        UndoManager.Record<PreviewItem> record = undoManager.pop();
        if (!applyUndo(record)) {
            undoManager.push(record);   // 原样压回，保持栈序不变
            return false;
        }
        return true;
    }

    /**
     * 应用一条**已被弹出**的结构类撤销记录（本方法<b>不触碰撤销栈</b>）。
     *
     * <p><b>为什么需要它</b>：GUI 的撤销流程必须先拿到记录、据类型做 UI 收尾
     * （选中跳转、缓存规则 (c)、重新预解析、日志），因此不能用 {@link #undo()}；
     * 但"结构如何恢复"这份实现必须只有一处。本方法即那唯一一处 ——
     * {@link #undo()} 与 GUI 都经它，从而消除"栈统一了、应用仍有两份"的重复。</p>
     *
     * <p><b>支持类型</b>：{@code REMOVE / REMOVE_GROUP / GROUP / UNGROUP / IMPORT / REORDER / MERGE_GROUPS}。
     * 其余（参数类）返回 {@code false} 且<b>不改变任何状态</b>，由调用方自行应用。</p>
     *
     * <p>拖拽类（{@code REORDER / MERGE_GROUPS}）自 Q0/P0 起纳入：它们此前落在 {@code default} 分支，
     * 是最后两处"GUI 把共享数据序交给 util 层改写"的间接写。恢复方式与
     * {@code GROUP} 同构 —— {@link GroupStructure#restoreStructure} 按操作前快照重建顶层顺序与
     * 各组成员（组对象复用，故组名/组参数保留），随后重建父组指针。</p>
     *
     * <p><b>受影响条目怎么拿</b>：用 {@link #applyUndoAffected} —— 它按"上一次
     * {@code applyUndo} 的记录"作答，因为布尔返回值必须保持既有语义
     * （5 个既有类型的调用点依赖它，不能为了多回传一个列表就改签名）。</p>
     *
     * @return true = 本类应用了该记录；false = 该类型本类尚未支持（未做任何变更）
     */
    public boolean applyUndo(UndoManager.Record<PreviewItem> record) {
        lastUndoAffected = List.of();
        if (record == null) {
            return false;
        }
        switch (record.type()) {
            case REMOVE, REMOVE_GROUP -> undoRemove(record);
            case GROUP -> undoGroup(record);
            case UNGROUP -> undoUngroup(record);
            case IMPORT -> undoImport(record);
            case REORDER, MERGE_GROUPS -> undoRestructure(record);
            default -> {
                return false;
            }
        }
        lastUndoKind = record.type().name();
        publish(WorkspaceChange.Kind.UNDO_APPLIED, undoAffectedOf(record));
        return true;
    }

    /**
     * 本次撤销"恢复进数据序"的条目（{@link WorkspaceChange#affected()} 的口径，见其 javadoc）。
     *
     * @param record 刚刚成功应用的那条记录（非 null）
     */
    private List<PreviewItem> undoAffectedOf(UndoManager.Record<PreviewItem> record) {
        return switch (record.type()) {
            // 拖拽类：与 applyUndoAffected() 同源（undoRestructure 刚写入 lastUndoAffected）
            case REORDER, MERGE_GROUPS -> lastUndoAffected == null ? List.of() : lastUndoAffected;
            // 撤销导入是把条目**移出**数据序，没有"恢复进数据序"的条目
            case IMPORT -> List.of();
            // REMOVE / REMOVE_GROUP / GROUP / UNGROUP：记录里的条目回到数据序
            default -> record.items() == null ? List.of() : record.items();
        };
    }

    /**
     * 上一次 {@link #applyUndo} 中<b>受影响</b>的条目（已过滤掉 {@code removed} 项）。
     *
     * <p><b>为什么是"配套查询"而不是改返回值</b>：{@code applyUndo} 的布尔语义已有 5 个类型的调用点
     * 依赖，升级为 record 会波及它们全部；而本方法只有拖拽类撤销一个调用点。代价是<b>有状态</b> ——
     * 故契约写死：<b>只能紧跟在一次成功的 {@link #applyUndo} 之后调用</b>，
     * 它描述的是那一次撤销的结果，不描述当前工作区状态。</p>
     *
     * <p>返回内容：{@code REORDER / MERGE_GROUPS} 记录里 {@code !removed} 的条目
     * （{@code REORDER} 为被拖项目、组移动时为空；{@code MERGE_GROUPS} 为被拖组成员副本）；
     * 其余类型（含未支持类型与 {@code record == null}）返回空列表。
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.GroupItem;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * 撤销栈（F4）：按"操作类型 + 受影响项目"记录压栈，后进先出弹出。深度 35 步，超出时丢弃最旧记录。
 *
 * <p>记录类型：REMOVE（隐藏式移除，含空组销毁）、IMPORT（增量导入）、
 * GROUP（合并为组，含操作前结构快照）、UNGROUP（拆分组，组名/参数随组对象保留）、
 * REMOVE_GROUP（整组移除，组名/参数随组对象保留）、REORDER（拖拽排序，含操作前结构快照）、
 * MERGE_GROUPS（拖拽组合并，含操作前结构快照，被拖组名/参数随组对象保留）、
 * APPLY_GLOBAL（将参数应用到全局，含应用前全局参数与全部独立参数快照）、
 * PARAM_SET（设置提取参数，条目/组/全局三作用域，含设置前参数）、
 * CLEAR_PARAMS（清除参数，条目/组作用域，含清除前参数快照，一次撤销全部恢复）。</p>
 *
 * @param <T> 列表项目类型
 */
public final class UndoManager<T> {

    /** 撤销栈深度上限（F4） */
    public static final int DEFAULT_LIMIT = 35;

    /** 可撤销操作类型（F4 5.4 + R12 + 阶段 7 + 条目独立参数需求） */
    public enum RecordType {
        REMOVE, IMPORT, GROUP, UNGROUP, REMOVE_GROUP, REORDER, MERGE_GROUPS, APPLY_GLOBAL, PARAM_SET, CLEAR_PARAMS
    }

    /**
     * 一条撤销记录。
     *
     * @param type             操作类型
     * @param items            受影响项目（按操作时顺序）；REORDER：被拖项目（组移动时为空，供撤销后重解析）；MERGE_GROUPS：被拖组成员副本
     * @param group            GROUP：新建的组；UNGROUP：被解散的组；REMOVE_GROUP：被移除的组；MERGE_GROUPS：被拖（销毁）的组；其余为 null
     * @param groupIndex       group 在顶层数据序中的位置（无组时为 -1）
     * @param groups           IMPORT：本次导入自动创建的组（撤销时随成员移除一并销毁）；其余为空
     * @param destroyedGroups  REMOVE/REMOVE_GROUP：因成员全部被移除而销毁的组（撤销时按索引恢复）
     * @param destroyedIndexes 与 destroyedGroups 一一对应的顶层索引
     * @param structureBefore  GROUP/REORDER/MERGE_GROUPS：操作前的顶层结构快照（撤销时恢复用）
     * @param applyGlobalImageMode            APPLY_GLOBAL：应用的是图片模式（false = 文本模式）
     * @param applyGlobalBefore               APPLY_GLOBAL：应用前的该模式全局参数（null = 未确认）
     * @param applyGlobalItemParamsBefore     APPLY_GLOBAL：应用前各条目该模式条目级参数快照（path → 参数，值可为 null）
     * @param applyGlobalGroupParamsBefore    APPLY_GLOBAL：应用前各组该模式参数快照（groupNo → 参数，值可为 null）
     * @param paramImageMode                  PARAM_SET：设置的是图片模式（false = 文本模式）
     * @param paramTargetPath                 PARAM_SET：目标条目路径（条目级参数；全局时为 null）
     * @param paramTargetGroupNo              PARAM_SET：目标组号（组参数；全局/条目级时为 null）
     * @param paramBefore                     PARAM_SET：设置前的该模式参数（null = 未设置）
     * @param clearImageMode                  CLEAR_PARAMS：清除的是图片模式（false = 文本模式）
     * @param clearItemParamsBefore           CLEAR_PARAMS：清除前各条目该模式条目级参数快照（path → 参数）
     * @param clearGroupParamsBefore          CLEAR_PARAMS：清除前各组该模式参数快照（groupNo → 参数）
     */
    public record Record<T>(RecordType type, List<T> items,
                            GroupItem<T> group, int groupIndex,
                            List<GroupItem<T>> groups,
                            List<GroupItem<T>> destroyedGroups, List<Integer> destroyedIndexes,
                            List<Object> structureBefore,
                            boolean applyGlobalImageMode,
                            AppConfig applyGlobalBefore,
                            Map<String, AppConfig> applyGlobalItemParamsBefore,
                            Map<Integer, AppConfig> applyGlobalGroupParamsBefore,
                            boolean paramImageMode,
                            String paramTargetPath,
                            Integer paramTargetGroupNo,
                            AppConfig paramBefore,
                            boolean clearImageMode,
                            Map<String, AppConfig> clearItemParamsBefore,
                            Map<Integer, AppConfig> clearGroupParamsBefore) {
        public Record {
            items = List.copyOf(items);
            groups = groups == null ? List.of() : List.copyOf(groups);
            destroyedGroups = List.copyOf(destroyedGroups);
            destroyedIndexes = List.copyOf(destroyedIndexes);
            structureBefore = List.copyOf(structureBefore);
            applyGlobalItemParamsBefore = applyGlobalItemParamsBefore == null
                    ? Map.of() : new HashMap<>(applyGlobalItemParamsBefore);
            applyGlobalGroupParamsBefore = applyGlobalGroupParamsBefore == null
                    ? Map.of() : new HashMap<>(applyGlobalGroupParamsBefore);
            clearItemParamsBefore = clearItemParamsBefore == null
                    ? Map.of() : new HashMap<>(clearItemParamsBefore);
            clearGroupParamsBefore = clearGroupParamsBefore == null
                    ? Map.of() : new HashMap<>(clearGroupParamsBefore);
        }

        /** 仅含类型与项目的记录（不含分组载荷；groups = 空） */
        public Record(RecordType type, List<T> items) {
            this(type, items, null, -1, List.of(), List.of(), List.of(), List.of(),
                    false, null, null, null, false, null, null, null,
                    false, null, null);
        }

        /** 结构类记录（GROUP/UNGROUP/REMOVE_GROUP/REORDER/MERGE_GROUPS；groups = 空） */
        public Record(RecordType type, List<T> items, GroupItem<T> group, int groupIndex,
                      List<GroupItem<T>> destroyedGroups, List<Integer> destroyedIndexes,
                      List<Object> structureBefore) {
            this(type, items, group, groupIndex, List.of(), destroyedGroups, destroyedIndexes,
                    structureBefore,
                    false, null, null, null, false, null, null, null,
                    false, null, null);
        }

        /** IMPORT 多组载荷：一次导入 = 一条记录携带全部自动创建的组（BC-5） */
        public Record(RecordType type, List<T> items, List<GroupItem<T>> groups) {
            this(type, items, null, -1, groups, List.of(), List.of(), List.of(),
                    false, null, null, null, false, null, null, null,
                    false, null, null);
        }
    }

    private final Deque<Record<T>> stack = new ArrayDeque<>();
    private final int limit;

    public UndoManager() {
        this(DEFAULT_LIMIT);
    }

    public UndoManager(int limit) {
        this.limit = limit;
    }

    /** 压入一条完整记录；超出深度上限时丢弃最旧记录 */
    public void push(Record<T> record) {
        stack.addLast(record);
        while (stack.size() > limit) {
            stack.removeFirst();
        }
    }

    /** 压入仅含类型与项目的记录（简单操作） */
    public void push(RecordType type, List<T> items) {
        push(new Record<>(type, items));
    }

    /** 弹出最新一条记录；栈空时返回 null */
    public Record<T> pop() {
        return stack.pollLast();
    }

    public boolean isEmpty() {
        return stack.isEmpty();
    }

    public int size() {
        return stack.size();
    }

    public void clear() {
        stack.clear();
    }
}

